using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using Kotoba;
class CoreTests {
 static int passed, failed;
 static DateTime now=new DateTime(2026,10,29,10,0,0,DateTimeKind.Local);
 static Word W(string id,int level=5) { return new Word {Id=id,Term=id,Reading=id,Meaning=id,Level=level}; }
 static void Check(bool ok,string message) { if(!ok)throw new Exception(message); }
 static void Test(string name,Action action) { try {action();passed++;Console.WriteLine("PASS "+name);} catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);} }
 static void Reject(Action action) { bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(InvalidDataException){rejected=true;}Check(rejected,"invalid input accepted"); }
 static void Main() {
 Test("ratings schedule four genuinely different intervals",()=>{ double[] days={1.0/1440,.25,1,4};for(int r=1;r<=4;r++){var s=new State();Scheduler.Grade(W("a"),s,r,now);Check(Math.Abs((s.Progress["a"].Due-now).TotalDays-days[r-1])<.00001,"wrong rating interval "+r);Check(s.Progress["a"].Reviews==1,"review missing");} });
 Test("repeat reviews grow interval and lapse resets it",()=>{var s=new State();var w=W("a");Scheduler.Grade(w,s,3,now);Scheduler.Grade(w,s,3,now.AddDays(1));Check(s.Progress["a"].Interval==2.5,"good growth");Scheduler.Grade(w,s,4,now.AddDays(4));Check(s.Progress["a"].Interval==7.5,"easy growth");Scheduler.Grade(w,s,1,now.AddDays(12));Check(s.Progress["a"].Lapses==1,"lapse missing");Check(Math.Abs(s.Progress["a"].Interval-1.0/1440)<.000001,"again not reset");});
 Test("due first, future excluded, level and daily quota enforced",()=>{var s=new State();s.Settings.DailyNew=1;s.Progress["due"]=new Progress{Id="due",Reviews=2,Interval=1,Due=now.AddDays(-1)};s.Progress["future"]=new Progress{Id="future",Reviews=1,Interval=1,Due=now.AddDays(1)};s.Progress["star"]=new Progress{Id="star",Star=true};var q=Scheduler.Queue(new List<Word>{W("star"),W("new"),W("future"),W("wrong",4),W("due")},s,now);Check(q.Count==2&&q[0].Id=="due"&&q[1].Id=="star","queue wrong");Scheduler.Grade(W("star"),s,1,now);q=Scheduler.Queue(new List<Word>{W("star"),W("new"),W("due")},s,now);Check(q.Count==1&&q[0].Id=="due","new quota not enforced");});
 Test("new counts once, review counts every grade, daily quota rolls over",()=>{var s=new State();s.Settings.DailyNew=1;var w=W("a");Scheduler.Grade(w,s,1,now);Scheduler.Grade(w,s,3,now.AddMinutes(2));Check(s.DailyNew["2026-10-29"]==1&&s.DailyReviews["2026-10-29"]==2,"daily counters wrong");Scheduler.Grade(w,s,3,now.AddDays(1));Check(!s.DailyNew.ContainsKey("2026-10-30"),"old word counted new");var q=Scheduler.Queue(new List<Word>{W("new")},s,now.AddDays(1));Check(q.Count==1,"next-day quota not reset");});
 Test("undo deep clone isolates every mutable branch",()=>{var s=new State();Scheduler.Grade(W("a"),s,3,now);var old=s.Clone();s.Settings.Level=1;s.Progress["a"].Star=true;s.DailyReviews["2026-10-29"]=99;Check(old.Settings.Level==5&&!old.Progress["a"].Star&&old.DailyReviews["2026-10-29"]==1,"clone shares mutable data");});
 Test("invalid grade leaves state untouched",()=>{var s=new State();Reject(()=>Scheduler.Grade(W("a"),s,5,now));Check(s.Progress.Count==0&&s.DailyReviews.Count==0,"failed rating mutated state");});
 Test("store persists, exports, rejects malformed imports without mutation",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-core-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try {var st=new Store(d);Scheduler.Grade(W("a"),st.Data,4,now);st.Save();var re=new Store(d);Check(re.Data.Progress["a"].Interval==4,"round trip lost data");Check(re.Data.Progress["a"].Due==now.AddDays(4),"round trip shifted local due time");string p=Path.Combine(d,"import.json");st.Export(p);re.Data.Settings.Level=1;re.Import(p);Check(re.Data.Settings.Level==5,"valid import failed");string before=File.ReadAllText(re.FilePath);string[] bad={"{}","null","{bad", "{\"Version\":9,\"Settings\":{},\"Progress\":{},\"DailyReviews\":{},\"DailyNew\":{}}"};foreach(var text in bad){File.WriteAllText(p,text);Reject(()=>re.Import(p));Check(re.Data.Progress.ContainsKey("a")&&File.ReadAllText(re.FilePath)==before,"bad import damaged existing progress");}var invalid=re.Data.Clone();invalid.Settings.DailyNew=-1;File.WriteAllText(p,new JavaScriptSerializer().Serialize(invalid));Reject(()=>re.Import(p));invalid=re.Data.Clone();invalid.Progress["a"].Reviews=-1;File.WriteAllText(p,new JavaScriptSerializer().Serialize(invalid));Reject(()=>re.Import(p));}finally{Directory.Delete(d,true);} });
 Test("backup recovers corrupt primary while retaining corrupt bytes",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-backup-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try {var st=new Store(d);Scheduler.Grade(W("a"),st.Data,3,now);st.Save();st.Data.Settings.Level=2;st.Save();File.WriteAllText(st.FilePath,"corrupt!");var re=new Store(d);Check(re.Data.Progress.ContainsKey("a"),"backup not recovered");Check(!String.IsNullOrEmpty(re.Warning),"recovery not communicated");Check(Directory.GetFiles(d,"*.corrupt-*").Length>0,"corrupt file not preserved");}finally{Directory.Delete(d,true);} });
 Test("import validates versions, null branches and large limits",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-limits-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try{var st=new Store(d);Scheduler.Grade(W("a"),st.Data,3,now);st.Save();string p=Path.Combine(d,"bad.json");var serializer=new JavaScriptSerializer();var invalid=st.Data.Clone();invalid.Version=2;File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));invalid=st.Data.Clone();invalid.Settings=null;File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));invalid=st.Data.Clone();invalid.Settings.DailyNew=1001;File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));invalid=st.Data.Clone();invalid.Progress["a"].Interval=100000;File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));invalid=st.Data.Clone();invalid.Progress["a"].Id="mismatch";File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));invalid=st.Data.Clone();invalid.DailyReviews["yesterday"]=1;File.WriteAllText(p,serializer.Serialize(invalid));Reject(()=>st.Import(p));Check(st.Data.Version==1&&st.Data.Progress["a"].Id=="a","bad input replaced data");}finally{Directory.Delete(d,true);}});
 Test("due-at-now included while zero new quota stops only new words",()=>{var s=new State();s.Settings.DailyNew=0;s.Progress["a"]=new Progress{Id="a",Reviews=1,Due=now,Interval=1};var q=Scheduler.Queue(new List<Word>{W("new"),W("a")},s,now);Check(q.Count==1&&q[0].Id=="a","zero quota blocks due review");});
 Test("locked corrupt primary still recovers backup in memory",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-locked-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try {var st=new Store(d);Scheduler.Grade(W("a"),st.Data,3,now);st.Save();st.Save();File.WriteAllText(st.FilePath,"corrupt!");using(var held=new FileStream(st.FilePath,FileMode.Open,FileAccess.Read,FileShare.Read)){var re=new Store(d);Check(re.Data.Progress.ContainsKey("a"),"usable backup discarded when primary replacement failed");}}finally{Directory.Delete(d,true);}});

 Test("multi-level queue combines selection with due-first and a shared daily allowance",()=>{var s=new State();s.Settings.Levels=new[]{5,4};s.Settings.DailyNew=2;s.DailyNew["2026-10-29"]=1;s.Progress["due4"]=new Progress{Id="due4",Reviews=1,Due=now.AddDays(-1),Interval=1};s.Progress["due3"]=new Progress{Id="due3",Reviews=1,Due=now.AddDays(-2),Interval=1};var q=Scheduler.Queue(new List<Word>{W("new5"),W("new4",4),W("due4",4),W("due3",3)},s,now);Check(q.Count==2&&q[0].Id=="due4"&&q[1].Id=="new5","multiple levels or shared quota failed");Check(Scheduler.SelectedLevels(s.Settings).SequenceEqual(new[]{5,4}),"selected levels not exposed");Check(Scheduler.IncludesLevel(s.Settings,4)&&!Scheduler.IncludesLevel(s.Settings,3),"membership incorrect");s.Settings.Levels=null;s.Settings.Level=2;Check(Scheduler.SelectedLevels(s.Settings).SequenceEqual(new[]{2}),"legacy level fallback failed");});
 Test("shuffle covers full new-word pool and remains stable while cards are graded",()=>{var s=new State();s.Settings.Levels=new[]{5,4};s.Settings.Shuffle=true;s.Settings.ShuffleSeed=42;s.Settings.DailyNew=20;var words=Enumerable.Range(0,100).Select(i=>W("word"+i,i%2==0?5:4)).ToList();var q=Scheduler.Queue(words,s,now);Check(q.Count==20,"wrong shuffled quota");Check(q.Any(w=>Int32.Parse(w.Id.Substring(4))>=20),"shuffled only quota-sized prefix");Check(q.Select(w=>w.Id).SequenceEqual(Scheduler.Queue(words,s,now).Select(w=>w.Id)),"order changed on redraw");Scheduler.Grade(q[0],s,3,now);Check(Scheduler.Queue(words,s,now).Select(w=>w.Id).SequenceEqual(q.Skip(1).Select(w=>w.Id)),"order changed after one grade");var clone=s.Clone();Check(Scheduler.Queue(words,clone,now).Select(w=>w.Id).SequenceEqual(Scheduler.Queue(words,s,now).Select(w=>w.Id)),"clone lost shuffle seed");s.Settings.ShuffleSeed=43;Check(!Scheduler.Queue(words,s,now).Select(w=>w.Id).SequenceEqual(q.Skip(1).Select(w=>w.Id)),"new seed did not reshuffle");});
 Test("shuffle never hides due reviews and daily quota resets across selected levels",()=>{var s=new State();s.Settings.Shuffle=true;s.Settings.Levels=new[]{5,4};s.Settings.DailyNew=1;var a=W("a",4);Scheduler.Grade(a,s,1,now);var words=new List<Word>{W("new5"),W("new4",4),a};var q=Scheduler.Queue(words,s,now.AddMinutes(2));Check(q.Count==1&&q[0].Id=="a","due review missing after daily new exhausted");q=Scheduler.Queue(words,s,now.AddDays(1));Check(q.Count==2&&q[0].Id=="a","next day did not reset multilevel allowance");});
 Test("clone retains new settings without sharing the level array",()=>{var s=new State();s.Settings.Levels=new[]{5,3};s.Settings.Shuffle=true;s.Settings.ShuffleSeed=7;s.Settings.AutoSpeak=false;s.Settings.Theme="Dark";s.Settings.Transparent=true;s.Settings.BackgroundOpacity=.45;var copy=s.Clone();s.Settings.Levels[0]=1;Check(copy.Settings.Levels!=null&&copy.Settings.Levels.SequenceEqual(new[]{5,3}),"level array shared or lost");Check(copy.Settings.Shuffle&&copy.Settings.ShuffleSeed==7&&!copy.Settings.AutoSpeak&&copy.Settings.Theme=="Dark"&&copy.Settings.Transparent&&copy.Settings.BackgroundOpacity==.45,"new settings lost during clone");});
 Test("old progress without new settings loads and keeps reviews and legacy level",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-old-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try {var state=new State();state.Settings.Level=3;Scheduler.Grade(W("existing",3),state,3,now);var ser=new JavaScriptSerializer();var raw=(Dictionary<string,object>)ser.DeserializeObject(ser.Serialize(state));raw["Settings"]=new Dictionary<string,object>{{"Level",3},{"DailyNew",20},{"Topmost",true},{"Compact",false},{"ShowReading",true}};File.WriteAllText(Path.Combine(d,"progress.json"),ser.Serialize(raw));var st=new Store(d);Check(st.Warning==null&&st.Data.Progress["existing"].Reviews==1,"legacy file rejected or progress reset");Check(Scheduler.SelectedLevels(st.Data.Settings).SequenceEqual(new[]{3}),"legacy level was reset to N5");Check(st.Data.Settings.AutoSpeak&&st.Data.Settings.Theme=="Light"&&!st.Data.Settings.Transparent&&!st.Data.Settings.Shuffle&&st.Data.Settings.BackgroundOpacity==.88,"legacy defaults incorrect");st.Data.Settings.Levels=new[]{3,4};st.Data.Settings.Shuffle=true;st.Data.Settings.Theme="Dark";st.Save();var loaded=new Store(d);Check(loaded.Data.Settings.Levels.SequenceEqual(new[]{3,4})&&loaded.Data.Settings.Shuffle&&loaded.Data.Settings.Theme=="Dark"&&loaded.Data.Settings.ShuffleSeed==st.Data.Settings.ShuffleSeed,"new settings not persisted");}finally{Directory.Delete(d,true);}});
 Test("invalid new settings are rejected without overwriting progress",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-v11-invalid-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try{var st=new Store(d);Scheduler.Grade(W("a"),st.Data,3,now);st.Save();string before=File.ReadAllText(st.FilePath);string p=Path.Combine(d,"bad.json");var changes=new Action<Settings>[]{x=>x.Levels=new int[0],x=>x.Levels=new[]{0,5},x=>x.Levels=new[]{6},x=>x.Levels=new[]{5,5},x=>x.Theme="unknown",x=>x.Theme=null,x=>x.BackgroundOpacity=.1,x=>x.BackgroundOpacity=1.1};foreach(var change in changes){var invalid=st.Data.Clone();change(invalid.Settings);File.WriteAllText(p,new JavaScriptSerializer().Serialize(invalid));Reject(()=>st.Import(p));Check(File.ReadAllText(st.FilePath)==before&&st.Data.Progress["a"].Reviews==1,"invalid settings damaged progress");}var opacity=st.Data.Settings.BackgroundOpacity;st.Data.Settings.BackgroundOpacity=Double.NaN;Reject(()=>st.Save());st.Data.Settings.BackgroundOpacity=opacity;}finally{Directory.Delete(d,true);}});

 Test("voice backend defaults to Neural and clone preserves Windows",()=>{var field=typeof(Settings).GetField("VoiceBackend");Check(field!=null,"VoiceBackend setting missing");var s=new State();Check((string)field.GetValue(s.Settings)=="Neural","default voice is not Neural");field.SetValue(s.Settings,"Windows");var copy=s.Clone();Check((string)field.GetValue(copy.Settings)=="Windows","clone lost voice preference");field.SetValue(s.Settings,"Neural");Check((string)field.GetValue(copy.Settings)=="Windows","clone shares voice settings");});
 Test("voice preference migrates old progress and persists the selected backend",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-voice-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try{var ser=new JavaScriptSerializer();var s=new State();Scheduler.Grade(W("a"),s,3,now);var raw=(Dictionary<string,object>)ser.DeserializeObject(ser.Serialize(s));((Dictionary<string,object>)raw["Settings"]).Remove("VoiceBackend");File.WriteAllText(Path.Combine(d,"progress.json"),ser.Serialize(raw));var st=new Store(d);var field=typeof(Settings).GetField("VoiceBackend");Check(field!=null,"VoiceBackend setting missing");Check(st.Warning==null&&st.Data.Progress["a"].Reviews==1&&(string)field.GetValue(st.Data.Settings)=="Neural","voice migration lost progress or default");field.SetValue(st.Data.Settings,"Windows");st.Save();var loaded=new Store(d);Check((string)field.GetValue(loaded.Data.Settings)=="Windows"&&loaded.Data.Progress["a"].Reviews==1,"voice preference did not persist");field.SetValue(loaded.Data.Settings,"Neural");loaded.Save();Check((string)field.GetValue(new Store(d).Data.Settings)=="Neural","Neural preference did not persist");}finally{Directory.Delete(d,true);}});
 Test("unsupported voice backends do not replace saved progress",()=>{string d=Path.Combine(Path.GetTempPath(),"kotoba-voice-invalid-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(d);try{var st=new Store(d);Scheduler.Grade(W("a"),st.Data,3,now);st.Save();string before=File.ReadAllText(st.FilePath);string p=Path.Combine(d,"bad.json");var ser=new JavaScriptSerializer();foreach(string value in new string[]{null,"","neural","Unknown"}){var raw=(Dictionary<string,object>)ser.DeserializeObject(ser.Serialize(st.Data));((Dictionary<string,object>)raw["Settings"])["VoiceBackend"]=value;File.WriteAllText(p,ser.Serialize(raw));Reject(()=>st.Import(p));Check(File.ReadAllText(st.FilePath)==before&&st.Data.Progress["a"].Reviews==1,"invalid voice backend damaged progress");}}finally{Directory.Delete(d,true);}});

 Console.WriteLine("RESULT "+passed+" passed, "+failed+" failed");Environment.ExitCode=failed==0?0:1;
 }
}
